import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";
import { SerialPort } from "serialport";

// Change 'COM3' with port Arduino (example: /dev/ttyUSB0 on Linux)
const port = new SerialPort({ path: 'COM4', baudRate: 115200 });

const server = new McpServer({
  name: "ArduinoControl",
  version: "1.0.0",
});

// MCP Tools
server.tool(
  "send-buzzer-commands",
  "Sending a package of note commands to Arduino to be executed independently",
  {
    steps: z.array(z.object({
      frequency: z.number().describe("Hz (0 for off)"),
      duration: z.number().describe("ms")
    }))
  },
  async ({ steps }) => {
    // Change Array To String Like This: "262,500|294,500|330,500"
    const commandString = steps
      .map(s => `${s.frequency},${s.duration}`)
      .join('|');
    port.write(commandString + "\n");

    return {
      success: true,
      content: [{ type: "text", text: "Command has been sent and is being processed by Arduino." }]
    };
  }
);

const transport = new StdioServerTransport();
await server.connect(transport);
